mapper.select:
select gmss.user_id as userId,
    count(*) as count,
    u.name  as name
    from linkx_dashboard.tb_group_msg_send_static gmss
    left join  icp_res.tb_im_user u on gmss.user_id = u.id

       u.id is not null

          and u.department_id in

             #{departmentId}



         and gmss.msg_time >= #{startTime}


         and gmss.msg_time <= #{endTime}


    group by user_id, u.name
    order by count desc
    limit ${topn}
